namespace Ds;

    use ArrayAccess;
    use Countable;
    use IteratorAggregate;
    use JsonSerializable;
    use OutOfBoundsException;
    use OutOfRangeException;
    use Traversable;
    use UnderflowException;

    /**
 * <div id="class.ds-collection" class="reference"> <h1 class="title">The Collection interface</h1>  <div class="partintro"><p class="verinfo">(PECL ds &gt;= 1.0.0)</p>  <div class="section" id="ds-collection.intro">   <h2 class="title">简介</h2>   <p class="simpara">    <span class="classname"><strong class="classname">Collection</strong></span> is the base interface which covers functionality    common to all the data structures in this library. It guarantees that all structures    are traversable, countable, and can be converted to json using <span class="function">{@link json_encode()}</span>.   </p>  </div>  <div class="section" id="ds-collection.synopsis">   <h2 class="title">接口摘要</h2>   <div class="classsynopsis"><div class="classsynopsisinfo">    <span class="modifier">interface</span> <strong class="interfacename"><strong class="interfacename">Ds\Collection</strong></strong>    <span class="modifier">extends</span>      <a href="https://php.net/manual/zh/class.countable.php" class="interfacename">Countable</a>,     <a href="https://php.net/manual/zh/class.iteratoraggregate.php" class="interfacename">IteratorAggregate</a>,     <a href="https://php.net/manual/zh/class.jsonserializable.php" class="interfacename">JsonSerializable</a> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-collection.clear.php" class="methodname" style="color:#CC7832">clear</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-collection.copy.php" class="methodname" style="color:#CC7832">copy</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-collection.php" class="type Ds\Collection" style="color:#EAB766">Ds\Collection</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-collection.isempty.php" class="methodname" style="color:#CC7832">isEmpty</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-collection.toarray.php" class="methodname" style="color:#CC7832">toArray</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 继承的方法 </div>    <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832">{@link Countable::count}</span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div>    <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832">{@link IteratorAggregate::getIterator}</span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.traversable.php" class="type Traversable" style="color:#EAB766">Traversable</a></span></div>    <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832">{@link JsonSerializable::jsonSerialize}</span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>   }</div>  </div>  <div class="section">   <h2 class="title">更新日志</h2>   <table class="doctable informaltable">         <thead>      <tr>       <th>版本</th>       <th>说明</th>      </tr>     </thead>     <tbody class="tbody">      <tr>       <td>PECL ds 1.4.0</td>       <td>        <span class="classname"><strong class="classname">Collection</strong></span> implements        <span class="interfacename"><a href="https://php.net/manual/zh/class.iteratoraggregate.php" class="interfacename">IteratorAggregate</a></span> now instead of just <span class="interfacename"><a href="https://php.net/manual/zh/class.traversable.php" class="interfacename">Traversable</a></span>. (This change came to the polyfill in 1.4.1.)       </td>      </tr>     </tbody>       </table>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link Ds\Collection::clear} — Removes all values</li><li>{@link Ds\Collection::copy} — Returns a shallow copy of the collection</li><li>{@link Ds\Collection::isEmpty} — Returns whether the collection is empty</li><li>{@link Ds\Collection::toArray} — Converts the collection to an array</li></ul></div>
 * 
     * Collection is the base interface which covers functionality common to all
     * the data structures in this library. It guarantees that all structures
     * are traversable, countable, and can be converted to json using
     * json_encode().
     * @package Ds
     *
     * @template-covariant TKey
     * @template-covariant TValue
     * @extends IteratorAggregate<TKey, TValue>
     */
    interface Collection extends Countable, IteratorAggregate, JsonSerializable
    {
        /**
 * <div id="ds-collection.clear" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Collection::clear</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Collection::clear</span> — <span class="dc-title">Removes all values</span></p> </div> <div class="refsect1 description" id="refsect1-ds-collection.clear-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Collection::clear</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">    Removes all values from the collection.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-collection.clear-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-collection.clear-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   没有返回值。  </p> </div> <div class="refsect1 examples" id="refsect1-ds-collection.clear-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Collection::clear()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$collection </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$collection</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">clear</span><span style="color: #007700">();<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$collection</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Vector&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;1<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;2<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;3<br>)<br>Ds\Vector&nbsp;Object<br>(<br>)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Removes all values from the collection.
         * @link https://www.php.net/manual/en/ds-collection.clear.php
         */
        public function clear(): void;

        /**
 * <div id="ds-collection.copy" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Collection::copy</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Collection::copy</span> — <span class="dc-title">Returns a shallow copy of the collection</span></p> </div> <div class="refsect1 description" id="refsect1-ds-collection.copy-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Collection::copy</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-collection.php" class="type Ds\Collection" style="color:#EAB766">Ds\Collection</a></span></div>  <p class="para rdfs-comment">    Returns a shallow copy of the collection.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-collection.copy-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-collection.copy-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   Returns a shallow copy of the collection.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-collection.copy-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Collection::copy()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$a </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$b </span><span style="color: #007700">= </span><span style="color: #9876AA">\$a</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">copy</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$b</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">push</span><span style="color: #007700">(</span><span style="color: #9876AA">4</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$a</span><span style="color: #007700">);<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$b</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Vector&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;1<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;2<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;3<br>)<br>Ds\Vector&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;1<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;2<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;3<br>&nbsp;&nbsp;&nbsp;&nbsp;[3]&nbsp;=&gt;&nbsp;4<br>)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Returns a shallow copy of the collection.
         * @link https://www.php.net/manual/en/ds-collection.copy.php
         * @return static
         */
        public function copy();

        /**
 * <div id="ds-collection.isempty" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Collection::isEmpty</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Collection::isEmpty</span> — <span class="dc-title">Returns whether the collection is empty</span></p> </div> <div class="refsect1 description" id="refsect1-ds-collection.isempty-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Collection::isEmpty</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="para rdfs-comment">    Returns whether the collection is empty.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-collection.isempty-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-collection.isempty-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    Returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if the collection is empty, <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> otherwise.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-collection.isempty-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Collection::isEmpty()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$a </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$b </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$a</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">isEmpty</span><span style="color: #007700">());<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$b</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">isEmpty</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">bool(false)<br>bool(true)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Returns whether the collection is empty.
         * @link https://www.php.net/manual/en/ds-collection.isempty.php
         * @return bool
         */
        public function isEmpty(): bool;

        /**
 * <div id="ds-collection.toarray" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Collection::toArray</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Collection::toArray</span> — <span class="dc-title">    Converts the collection to an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>  </span></p> </div> <div class="refsect1 description" id="refsect1-ds-collection.toarray-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Collection::toArray</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>  <p class="para rdfs-comment">    Converts the collection to an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     </p><p class="para">        Casting to an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> is not supported yet.    </p>  </blockquote> </div> <div class="refsect1 parameters" id="refsect1-ds-collection.toarray-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-collection.toarray-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    An <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> containing all the values in the same order as the collection.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-collection.toarray-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Collection::toArray()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$collection </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">toArray</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">array(3)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;int(3)<br>}</blockquote></div>   </div>  </div> </div></div>
 * 
         * Converts the collection to an array.
         * <p><b>Note:</b> Casting to an array is not supported yet.</p>
         * @link https://www.php.net/manual/en/ds-collection.toarray.php
         * @return array<TValue> An array containing all the values in the same order as
         * the collection.
         */
        public function toArray(): array;
    }

    /**
 * <div id="class.ds-hashable" class="reference"> <h1 class="title">The Hashable interface</h1>  <div class="partintro"><p class="verinfo">(PECL ds &gt;= 1.0.0)</p>  <div class="section" id="ds-hashable.intro">   <h2 class="title">简介</h2>   <p class="simpara">        Hashable is an interface which allows objects to be used as keys.        It’s an alternative to <span class="function">{@link spl_object_hash()}</span>,        which determines an object’s hash based on its handle:        this means that two objects that are considered equal by an implicit        definition would not be treated as equal because they are not the same instance.   </p>   <p class="simpara">        <span class="function">{@link hash()}</span> is used to return a scalar value to be used as        the object's hash value, which determines where it goes in the hash table.        While this value does not have to be unique, objects which are equal must        have the same hash value.    </p>    <p class="simpara">        <span class="function"><strong style="color:#CC7832">equals()</strong></span> is used to determine if two objects are equal.        It's guaranteed that the comparing object will be an instance of the same class        as the subject.    </p>  </div>  <div class="section" id="ds-hashable.synopsis">   <h2 class="title">接口摘要</h2>   <div class="classsynopsis"><div class="classsynopsisinfo">    <span class="modifier">interface</span> <strong class="interfacename"><strong class="interfacename">Ds\Hashable</strong></strong> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-hashable.equals.php" class="methodname" style="color:#CC7832">equals</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span> <span class="parameter" style="color:#3A95FF">\$obj</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-hashable.hash.php" class="methodname" style="color:#CC7832">hash</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>   }</div>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link Ds\Hashable::equals} — Determines whether an object is equal to the current instance</li><li>{@link Ds\Hashable::hash} — Returns a scalar value to be used as a hash value</li></ul></div>
 * 
     * Hashable is an interface which allows objects to be used as keys. It’s
     * an alternative to spl_object_hash(), which determines an object’s hash
     * based on its <b>handle:</b> this means that two objects that are considered
     * equal by an implicit definition would not treated as equal because they
     * are not the same instance.
     *
     * hash() is used to return a scalar value to be used as the object's hash
     * value, which determines where it goes in the hash table. While this value
     * does not have to be unique, objects which are equal must have the same
     * hash value.
     *
     * equals() is used to determine if two objects are equal. It's guaranteed
     * that the comparing object will be an instance of the same class as the
     * subject.
     * @package Ds
     */
    interface Hashable
    {
        /**
 * <div id="ds-hashable.equals" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Hashable::equals</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Hashable::equals</span> — <span class="dc-title">Determines whether an object is equal to the current instance</span></p> </div> <div class="refsect1 description" id="refsect1-ds-hashable.equals-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Hashable::equals</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span> <span class="parameter" style="color:#3A95FF">\$obj</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="para rdfs-comment">    Determines whether another object is equal to the current instance.  </p>  <p class="para">    This method allows objects to be used as keys in structures such as    <span class="classname"><a href="https://php.net/manual/zh/class.ds-map.php" class="classname">Ds\Map</a></span> and <span class="classname"><a href="https://php.net/manual/zh/class.ds-set.php" class="classname">Ds\Set</a></span>, or any    other lookup structure that honors this interface.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     </p><p class="para">        It's guaranteed that <span class="parameter" style="color:#3A95FF">obj</span> is an instance of the same class.    </p>  </blockquote>  <div class="caution"><strong class="caution">警告</strong>    <p class="para">        It's important that objects which are equal also have the same hash value.        See <span class="function">{@link Ds\Hashable::hash()}</span>.    </p>  </div> </div> <div class="refsect1 parameters" id="refsect1-ds-hashable.equals-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">obj</span></dt>    <dd>     <p class="para">        The object to compare the current instance to, which is always an instance of        the same class.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-hashable.equals-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if equal, <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> otherwise.  </p> </div></div>
 * 
         * Determines whether another object is equal to the current instance.
         *
         * This method allows objects to be used as keys in structures such as
         * Ds\Map and Ds\Set, or any other lookup structure that honors this
         * interface.
         *
         * <b>Note:</b> It's guaranteed that $obj is an instance of the same class.
         *
         * <b>Caution:</b> It's important that objects which are equal also have the
         * same hash value.
         * @see https://www.php.net/manual/en/ds-hashable.hash.php
         * @link https://www.php.net/manual/en/ds-hashable.equals.php
         * @param object $obj The object to compare the current instance to,
         * which is always an instance of the same class.
         *
         * @return bool True if equal, false otherwise.
         */
        public function equals($obj): bool;

        /**
 * <div id="ds-hashable.hash" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Hashable::hash</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Hashable::hash</span> — <span class="dc-title">Returns a scalar value to be used as a hash value</span></p> </div> <div class="refsect1 description" id="refsect1-ds-hashable.hash-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Hashable::hash</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>  <p class="para rdfs-comment">    Returns a scalar value to be used as the hash value of the objects.  </p>  <p class="para">    While the hash value does not define equality, all objects that are equal according to <span class="function">{@link Ds\Hashable::equals()}</span>    must have the same hash value. Hash values of equal objects don't have to be unique, for example    you could just return <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> for all objects and nothing would break - the only    implication would be that hash tables then turn into linked lists because all    your objects will be hashed to the same bucket. It's therefore very important    that you pick a good hash value, such as an ID or email address. </p>  <p class="para">    This method allows objects to be used as keys in structures such as    <span class="classname"><a href="https://php.net/manual/zh/class.ds-map.php" class="classname">Ds\Map</a></span> and <span class="classname"><a href="https://php.net/manual/zh/class.ds-set.php" class="classname">Ds\Set</a></span>, or any    other lookup structure that honors this interface.  </p>  <div class="caution"><strong class="caution">警告</strong>    <p class="para">        Do not pick a value that might change within the object, such as a public        property. Hash table lookups would fail because the hash has changed.    </p>  </div>  <div class="caution"><strong class="caution">警告</strong>    <p class="para">        All objects that are equal must have the same hash value.    </p>  </div> </div> <div class="refsect1 parameters" id="refsect1-ds-hashable.hash-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-hashable.hash-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    A scalar value to be used as this object's hash value.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-hashable.hash-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Hashable::hash()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br></span><span style="color: #007700">class </span><span style="color: #9876AA">HashableObject </span><span style="color: #007700">implements </span><span style="color: #9876AA">\Ds\Hashable<br></span><span style="color: #007700">{<br>    private </span><span style="color: #9876AA">\$name</span><span style="color: #007700">;<br>    private </span><span style="color: #9876AA">\$email</span><span style="color: #007700">;<br><br>    public function </span><span style="color: #9876AA">__construct</span><span style="color: #007700">(</span><span style="color: #9876AA">\$name</span><span style="color: #007700">, </span><span style="color: #9876AA">\$email</span><span style="color: #007700">)<br>    {<br>        </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">name  </span><span style="color: #007700">= </span><span style="color: #9876AA">\$name</span><span style="color: #007700">;<br>        </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">email </span><span style="color: #007700">= </span><span style="color: #9876AA">\$email</span><span style="color: #007700">;<br>    }<br><br>    </span><span style="color: #FF8000">//*<br>     * Should return the same value for all equal objects, but doesn't have to<br>     * be unique. This value will not be used to determine equality.<br>     <br>    </span><span style="color: #007700">public function </span><span style="color: #9876AA">hash</span><span style="color: #007700">()<br>    {<br>        return </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">email</span><span style="color: #007700">;<br>    }<br><br>    </span><span style="color: #FF8000">//*<br>     * This determines equality, usually during a hash table lookup to determine<br>     * if the bucket's key matches the lookup key. The hash has to be equal if<br>     * the objects are equal, otherwise this determination wouldn't be reached.<br>     <br>    </span><span style="color: #007700">public function </span><span style="color: #9876AA">equals</span><span style="color: #007700">(</span><span style="color: #9876AA">\$obj</span><span style="color: #007700">): </span><span style="color: #9876AA">bool<br>    </span><span style="color: #007700">{<br>        return </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">name  </span><span style="color: #007700">=== </span><span style="color: #9876AA">\$obj</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">name<br>            </span><span style="color: #007700">&amp;&amp; </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">email </span><span style="color: #007700">=== </span><span style="color: #9876AA">\$obj</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">email</span><span style="color: #007700">;<br>    }<br>}<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div> </div></div>
 * 
         * Returns a scalar value to be used as the hash value of the objects.
         *
         * While the hash value does not define equality, all objects that are
         * equal according to Ds\Hashable::equals() must have the same hash
         * value. Hash values of equal objects don't have to be unique, for
         * example you could just return TRUE for all objects and nothing
         * would break - the only implication would be that hash tables then
         * turn into linked lists because all your objects will be hashed to
         * the same bucket. It's therefore very important that you pick a good
         * hash value, such as an ID or email address.
         *
         * This method allows objects to be used as keys in structures such as
         * Ds\Map and Ds\Set, or any other lookup structure that honors this
         * interface.
         *
         * <b>Caution:</b> Do not pick a value that might change within the object,
         * such as a public property. Hash table lookups would fail because
         * the hash has changed.
         *
         * <b>Caution:</b> All objects that are equal must have the same hash value.
         *
         * @return mixed A scalar value to be used as this object's hash value.
         * @link https://www.php.net/manual/en/ds-hashable.hash.php
         */
        public function hash();
    }

    /**
 * <div id="class.ds-sequence" class="reference"> <h1 class="title">The Sequence interface</h1>  <div class="partintro"><p class="verinfo">(PECL ds &gt;= 1.0.0)</p>  <div class="section" id="ds-sequence.intro">   <h2 class="title">简介</h2>   <p class="para">        A Sequence describes the behaviour of values arranged in a single, linear dimension.        Some languages refer to this as a "List". It’s similar to an array that uses        incremental integer keys, with the exception of a few characteristics:        </p><ul class="simplelist">            <li>Values will always be indexed as [0, 1, 2, …, size - 1].</li>            <li>Only allowed to access values by index in the range [0, size - 1].</li>        </ul>        <p class="para">        Use cases:        </p><ul class="simplelist">            <li>Wherever you would use an array as a list (not concerned with keys).</li>            <li>A more efficient alternative to                <span class="classname"><a href="https://php.net/manual/zh/class.spldoublylinkedlist.php" class="classname">SplDoublyLinkedList</a></span> and                <span class="classname"><a href="https://php.net/manual/zh/class.splfixedarray.php" class="classname">SplFixedArray</a></span>.            </li>        </ul>     </div>  <div class="section" id="ds-sequence.synopsis">   <h2 class="title">接口摘要</h2>   <div class="classsynopsis"><div class="classsynopsisinfo">    <span class="modifier">interface</span> <strong class="interfacename"><strong class="interfacename">Ds\Sequence</strong></strong>    <span class="modifier">extends</span>      <a href="https://php.net/manual/zh/class.ds-collection.php" class="interfacename">Ds\Collection</a>,     <a href="https://php.net/manual/zh/class.arrayaccess.php" class="interfacename">ArrayAccess</a> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-sequence.allocate.php" class="methodname" style="color:#CC7832">allocate</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$capacity</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-sequence.apply.php" class="methodname" style="color:#CC7832">apply</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$callback</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-sequence.capacity.php" class="methodname" style="color:#CC7832">capacity</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-sequence.contains.php" class="methodname" style="color:#CC7832">contains</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">...\$values</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-sequence.filter.php" class="methodname" style="color:#CC7832">filter</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$callback</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-sequence.php" class="type Ds\Sequence" style="color:#EAB766">Ds\Sequence</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-sequence.find.php" class="methodname" style="color:#CC7832">find</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-sequence.first.php" class="methodname" style="color:#CC7832">first</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-sequence.get.php" class="methodname" style="color:#CC7832">get</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$index</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-sequence.insert.php" class="methodname" style="color:#CC7832">insert</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$index</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">...\$values</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-sequence.join.php" class="methodname" style="color:#CC7832">join</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$glue</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-sequence.last.php" class="methodname" style="color:#CC7832">last</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-sequence.map.php" class="methodname" style="color:#CC7832">map</a></span>(<span class="methodpa