ct</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-sequence.set.php" class="methodname" style="color:#CC7832">set</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$index</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-sequence.shift.php" class="methodname" style="color:#CC7832">shift</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-sequence.slice.php" class="methodname" style="color:#CC7832">slice</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$index</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$length</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-sequence.php" class="type Ds\Sequence" style="color:#EAB766">Ds\Sequence</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-sequence.sort.php" class="methodname" style="color:#CC7832">sort</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$comparator</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-sequence.sorted.php" class="methodname" style="color:#CC7832">sorted</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$comparator</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-sequence.php" class="type Ds\Sequence" style="color:#EAB766">Ds\Sequence</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-sequence.sum.php" class="methodname" style="color:#CC7832">sum</a></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.float.php" class="type float" style="color:#EAB766">float</a></span></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-sequence.unshift.php" class="methodname" style="color:#CC7832">unshift</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$values</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 继承的方法 </div>    <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832">{@link Ds\Collection::clear}</span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832">{@link Ds\Collection::copy}</span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-collection.php" class="type Ds\Collection" style="color:#EAB766">Ds\Collection</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832">{@link Ds\Collection::isEmpty}</span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832">{@link Ds\Collection::toArray}</span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>    <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832">{@link Countable::count}</span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div>    <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832">{@link IteratorAggregate::getIterator}</span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.traversable.php" class="type Traversable" style="color:#EAB766">Traversable</a></span></div>    <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832">{@link JsonSerializable::jsonSerialize}</span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>    <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832">{@link ArrayAccess::offsetExists}</span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$offset</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832">{@link ArrayAccess::offsetGet}</span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$offset</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832">{@link ArrayAccess::offsetSet}</span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$offset</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832">{@link ArrayAccess::offsetUnset}</span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$offset</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>   }</div>  </div>  <div class="section">   <h2 class="title">更新日志</h2>   <p class="para">    </p><table class="doctable informaltable">           <thead>       <tr>        <th>版本</th>        <th>说明</th>       </tr>      </thead>      <tbody class="tbody">       <tr>        <td>PECL ds 1.3.0</td>        <td>         The interface now extends <span class="classname"><a href="https://php.net/manual/zh/class.arrayaccess.php" class="classname">ArrayAccess</a></span>.        </td>       </tr>      </tbody>         </table>     </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link Ds\Sequence::allocate} — Allocates enough memory for a required capacity</li><li>{@link Ds\Sequence::apply} — Updates all values by applying a callback function to each value</li><li>{@link Ds\Sequence::capacity} — Returns the current capacity</li><li>{@link Ds\Sequence::contains} — Determines if the sequence contains given values</li><li>{@link Ds\Sequence::filter} — Creates a new sequence using a callable to    determine which values to include</li><li>{@link Ds\Sequence::find} — Attempts to find a value's index</li><li>{@link Ds\Sequence::first} — Returns the first value in the sequence</li><li>{@link Ds\Sequence::get} — Returns the value at a given index</li><li>{@link Ds\Sequence::insert} — Inserts values at a given index</li><li>{@link Ds\Sequence::join} — Joins all values together as a string</li><li>{@link Ds\Sequence::last} — Returns the last value</li><li>{@link Ds\Sequence::map} — Returns the result of applying a callback to each value</li><li>{@link Ds\Sequence::merge} — Returns the result of adding all given values to the sequence</li><li>{@link Ds\Sequence::pop} — Removes and returns the last value</li><li>{@link Ds\Sequence::push} — Adds values to the end of the sequence</li><li>{@link Ds\Sequence::reduce} — Reduces the sequence to a single value using a callback function</li><li>{@link Ds\Sequence::remove} — Removes and returns a value by index</li><li>{@link Ds\Sequence::reverse} — Reverses the sequence in-place</li><li>{@link Ds\Sequence::reversed} — Returns a reversed copy</li><li>{@link Ds\Sequence::rotate} — Rotates the sequence by a given number of rotations</li><li>{@link Ds\Sequence::set} — Updates a value at a given index</li><li>{@link Ds\Sequence::shift} — Removes and returns the first value</li><li>{@link Ds\Sequence::slice} — Returns a sub-sequence of a given range</li><li>{@link Ds\Sequence::sort} — Sorts the sequence in-place</li><li>{@link Ds\Sequence::sorted} — Returns a sorted copy</li><li>{@link Ds\Sequence::sum} — Returns the sum of all values in the sequence</li><li>{@link Ds\Sequence::unshift} — Adds values to the front of the sequence</li></ul></div>
 * 
     * A Sequence describes the behaviour of values arranged in a single,
     * linear dimension. Some languages refer to this as a "List". It’s
     * similar to an array that uses incremental integer keys, with the
     * exception of a few characteristics:
     * <ul>
     * <li>Values will always be indexed as [0, 1, 2, …, size - 1].</li>
     * <li>Only allowed to access values by index in the range [0, size - 1].</li>
     * </ul>
     * <br>
     * Use cases:
     * <ul>
     * <li>Wherever you would use an array as a list (not concerned with keys).</li>
     * <li>A more efficient alternative to SplDoublyLinkedList and SplFixedArray.</li>
     * </ul>
     * @package Ds
     * @template TValue
     * @extends Collection<int, TValue>
     */
    interface Sequence extends Collection, ArrayAccess
    {
        /**
 * <div id="ds-sequence.allocate" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::allocate</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::allocate</span> — <span class="dc-title">Allocates enough memory for a required capacity</span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.allocate-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::allocate</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$capacity</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">    Ensures that enough memory is allocated for a required capacity.    This removes the need to reallocate the internal buffer as values are added.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.allocate-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">capacity</span></dt>    <dd>     <span class="simpara">        The number of values for which capacity should be allocated.     </span>     <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:         <span class="simpara">            Capacity will stay the same if this value is less than or equal to the            current capacity.        </span>    </p></blockquote>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.allocate-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    没有返回值。  </p> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.allocate-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::allocate()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">();<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">capacity</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">\$vector</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">allocate</span><span style="color: #007700">(</span><span style="color: #9876AA">100</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">capacity</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(10)<br>int(100)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Ensures that enough memory is allocated for a required capacity.
         * This removes the need to reallocate the internal as values are added.
         *
         * @param int $capacity The number of values for which capacity should
         * be allocated.<p><b>Note:</b> Capacity will stay the same if this value is
         * less than or equal to the current capacity.</p>
         * @link https://www.php.net/manual/en/ds-sequence.allocate.php
         */
        public function allocate(int $capacity): void;

        /**
 * <div id="ds-sequence.apply" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::apply</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::apply</span> — <span class="dc-title">Updates all values by applying a callback function to each value</span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.apply-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::apply</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$callback</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">    Updates all values by applying a <span class="parameter" style="color:#3A95FF">callback</span> function to    each value in the sequence.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.apply-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">callback</span></dt>    <dd>        <p class="para">            </p><div class="methodsynopsis dc-description">                <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><span class="replaceable">callback</span></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>                <span class="simpara">            A <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> to apply to each value in the sequence.        </span>        <span class="simpara">            The callback should return what the value should be replaced by.        </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.apply-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    没有返回值。  </p> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.apply-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::apply()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">apply</span><span style="color: #007700">(function(</span><span style="color: #9876AA">\$value</span><span style="color: #007700">) { return </span><span style="color: #9876AA">\$value </span><span style="color: #007700">* </span><span style="color: #9876AA">2</span><span style="color: #007700">; });<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Vector&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;2<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;4<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;6<br>)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Updates all values by applying a callback function to each value in
         * the sequence.
         * @param callable(TValue): TValue $callback A callable to apply to each value in the
         * sequence. The callback should return what the value should be
         * replaced by.
         * <code>callback ( mixed $value ) : mixed</code>
         * @link https://www.php.net/manual/en/ds-sequence.apply.php
         */
        public function apply(callable $callback): void;

        /**
 * <div id="ds-sequence.capacity" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::capacity</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::capacity</span> — <span class="dc-title">Returns the current capacity</span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.capacity-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::capacity</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div>  <p class="simpara">    Returns the current capacity.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.capacity-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.capacity-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    The current capacity.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.capacity-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::capacity()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">();<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">capacity</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">push</span><span style="color: #007700">(...</span><span style="color: #9876AA">range</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">50</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">capacity</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">[] = </span><span style="color: #DD0000">"a"</span><span style="color: #007700">;<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">capacity</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(10)<br>int(50)<br>int(75)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Returns the current capacity.
         * @return int The current capacity.
         * @link https://www.php.net/manual/en/ds-sequence.capacity.php
         */
        public function capacity(): int;

        /**
 * <div id="ds-sequence.contains" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::contains</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::contains</span> — <span class="dc-title">Determines if the sequence contains given values</span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.contains-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::contains</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">...\$values</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="simpara">    Determines if the sequence contains all values.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.contains-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">values</span></dt>    <dd>     <span class="simpara">        Values to check.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.contains-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> if any of the provided <span class="parameter" style="color:#3A95FF">values</span> are not in the    sequence, <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> otherwise.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.contains-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::contains()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #DD0000">'a'</span><span style="color: #007700">, </span><span style="color: #DD0000">'b'</span><span style="color: #007700">, </span><span style="color: #DD0000">'c'</span><span style="color: #007700">, </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">contains</span><span style="color: #007700">(</span><span style="color: #DD0000">'a'</span><span style="color: #007700">));                </span><span style="color: #FF8000">// true<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">contains</span><span style="color: #007700">(</span><span style="color: #DD0000">'a'</span><span style="color: #007700">, </span><span style="color: #DD0000">'b'</span><span style="color: #007700">));           </span><span style="color: #FF8000">// true<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">contains</span><span style="color: #007700">(</span><span style="color: #DD0000">'c'</span><span style="color: #007700">, </span><span style="color: #DD0000">'d'</span><span style="color: #007700">));           </span><span style="color: #FF8000">// false<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">contains</span><span style="color: #007700">(...[</span><span style="color: #DD0000">'c'</span><span style="color: #007700">, </span><span style="color: #DD0000">'b'</span><span style="color: #007700">, </span><span style="color: #DD0000">'a'</span><span style="color: #007700">])); </span><span style="color: #FF8000">// true<br><br>// Always strict<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">contains</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">));                  </span><span style="color: #FF8000">// true<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">contains</span><span style="color: #007700">(</span><span style="color: #DD0000">'1'</span><span style="color: #007700">));                </span><span style="color: #FF8000">// false<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">contains</span><span style="color: #007700">(...[]));               </span><span style="color: #FF8000">// true<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">bool(true)<br>bool(true)<br>bool(false)<br>bool(true)<br>bool(true)<br>bool(false)<br>bool(true)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Determines if the sequence contains all values.
         * @param TValue ...$values Values to check.
         * @return bool FALSE if any of the provided values are not in the
         * sequence, TRUE otherwise.
         * @link https://www.php.net/manual/en/ds-sequence.contains.php
         */
        public function contains(...$values): bool;

        /**
 * <div id="ds-sequence.filter" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::filter</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::filter</span> — <span class="dc-title">    Creates a new sequence using a <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> to    determine which values to include </span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.filter-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::filter</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$callback</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-sequence.php" class="type Ds\Sequence" style="color:#EAB766">Ds\Sequence</a></span></div>  <p class="simpara">    Creates a new sequence using a <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> to    determine which values to include.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.filter-parameters">  <h3 class="title">参数</h3> <dl>        <dt><span class="parameter" style="color:#3A95FF">callback</span></dt>    <dd>        <p class="para">            </p><div class="methodsynopsis dc-description"><span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><span class="replaceable">callback</span></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>                <span class="simpara">            Optional <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> which returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if the value should be included, <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> otherwise.        </span>        <span class="simpara">            If a callback is not provided, only values which are <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>            (see <a href="https://php.net/manual/zh/language.types.boolean.php#language.types.boolean.casting" class="link">converting to boolean</a>)            will be included.        </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.filter-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    A new sequence containing all the values for which    either the <span class="parameter" style="color:#3A95FF">callback</span> returned <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>, or all values that    convert to <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if a <span class="parameter" style="color:#3A95FF">callback</span> was not provided.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.filter-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::filter()</strong></span> example using callback function</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #9876AA">4</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">filter</span><span style="color: #007700">(function(</span><span style="color: #9876AA">\$value</span><span style="color: #007700">) {<br>    return </span><span style="color: #9876AA">\$value </span><span style="color: #007700">% </span><span style="color: #9876AA">2 </span><span style="color: #007700">== </span><span style="color: #9876AA">0</span><span style="color: #007700">;<br>}));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(Ds\Vector)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;int(4)<br>}</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">Ds\Sequence::filter()</strong></span> example without a callback function</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">'a'</span><span style="color: #007700">, </span><span style="color: #9876AA">true</span><span style="color: #007700">, </span><span style="color: #9876AA">false</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">filter</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(Ds\Vector)#2&nbsp;(3)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"a"<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;bool(true)<br>}</blockquote></div>   </div>  </div> </div></div>
 * 
         * Creates a new sequence using a callable to determine which values
         * to include.
         * @param null|callable(TValue): bool $callback Optional callable which returns TRUE if the
         * value should be included, FALSE otherwise. If a callback is not
         * provided, only values which are TRUE (see converting to boolean) will
         * be included.
         * <code>callback ( mixed $value ) : bool</code>
         * @return Sequence<TValue> A new sequence containing all the values for which
         * either the callback returned TRUE, or all values that convert to
         * TRUE if a callback was not provided.
         * @link https://www.php.net/manual/en/ds-sequence.filter.php
         */
        public function filter(?callable $callback = null);

        /**
 * <div id="ds-sequence.find" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::find</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::find</span> — <span class="dc-title">    Attempts to find a value's index  </span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.find-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::find</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>  <p class="simpara">    Returns the index of the <span class="parameter" style="color:#3A95FF">value</span>, or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> if not found.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.find-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">value</span></dt>    <dd>     <span class="simpara">        The value to find.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.find-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    The index of the value, or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> if not found.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:         <span class="simpara">            Values will be compared by value and by type.        </span>    </p></blockquote> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.find-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::find()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #DD0000">"a"</span><span style="color: #007700">, </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">true</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">find</span><span style="color: #007700">(</span><span style="color: #DD0000">"a"</span><span style="color: #007700">)); </span><span style="color: #FF8000">// 0<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">find</span><span style="color: #007700">(</span><span style="color: #DD0000">"b"</span><span style="color: #007700">)); </span><span style="color: #FF8000">// false<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">find</span><span style="color: #007700">(</span><span style="color: #DD0000">"1"</span><span style="color: #007700">)); </span><span style="color: #FF8000">// false<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">find</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">));   </span><span style="color: #FF8000">// 1<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(0)<br>bool(false)<br>bool(false)<br>int(1)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Returns the index of the value, or FALSE if not found.
         * @param TValue $value The value to find.
         * @return int|false The index of the value, or FALSE if not found.
         * @link https://www.php.net/manual/en/ds-sequence.find.php
         */
        public function find($value);

        /**
 * <div id="ds-sequence.first" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::first</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::first</span> — <span class="dc-title">Returns the first value in the sequence</span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.first-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::first</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>  <p class="simpara">    Returns the first value in the sequence.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.first-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.first-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    The first value in the sequence.  </p> </div> <div class="refsect1 errors" id="refsect1-ds-sequence.first-errors">  <h3 class="title">错误／异常</h3>  <p class="simpara">   <span class="exceptionname"><a href="https://php.net/manual/zh/class.underflowexception.php" class="exceptionname">UnderflowException</a></span> if empty.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.first-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::first()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">first</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(1)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Returns the first value in the sequence.
         * @return TValue The first value in the sequence.
         * @throws UnderflowException if empty.
         * @link https://www.php.net/manual/en/ds-sequence.first.php
         */
        public function first();

        /**
 * <div id="ds-sequence.get" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::get</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::get</span> — <span class="dc-title">Returns the value at a given index</span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.get-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::get</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$index</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>  <p class="simpara">    Returns the value at a given index.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.get-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">index</span></dt>    <dd>     <span class="simpara">        The index to access, starting at 0.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.get-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    The value at the requested index.  </p> </div> <div class="refsect1 errors" id="refsect1-ds-sequence.get-errors">  <h3 class="title">错误／异常</h3>  <p class="simpara">   <span class="exceptionname"><a href="https://php.net/manual/zh/class.outofrangeexception.php" class="exceptionname">OutOfRangeException</a></span> if the index is not valid.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.get-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::get()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #DD0000">"a"</span><span style="color: #007700">, </span><span style="color: #DD0000">"b"</span><span style="color: #007700">, </span><span style="color: #DD0000">"c"</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">get</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">get</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">get</span><span style="color: #007700">(</span><span style="color: #9876AA">2</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">string(1)&nbsp;"a"<br>string(1)&nbsp;"b"<br>string(1)&nbsp;"c"</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">Ds\Sequence::get()</strong></span> example using array syntax</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #DD0000">"a"</span><span style="color: #007700">, </span><span style="color: #DD0000">"b"</span><span style="color: #007700">, </span><span style="color: #DD0000">"c"</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">[</span><span style="color: #9876AA">0</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">[</span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">[</span><span style="color: #9876AA">2</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">string(1)&nbsp;"a"<br>string(1)&nbsp;"b"<br>string(1)&nbsp;"c"</blockquote></div>   </div>  </div> </div></div>
 * 
         * Returns the value at a given index.
         * @param int $index The index to access, starting at 0.
         * @return TValue The value at the requested index.
         * @throws OutOfRangeException if the index is not valid.
         * @link https://www.php.net/manual/en/ds-sequence.get.php
         */
        public function get(int $index);

        /**
 * <div id="ds-sequence.insert" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::insert</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::insert</span> — <span class="dc-title">Inserts values at a given index</span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.insert-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::insert</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$index</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">...\$values</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">    Inserts values into the sequence at a given index.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.insert-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">index</span></dt>    <dd>     <p class="para">        The index at which to insert. <span class="code">0 &lt;= index &lt;= count</span>     </p>     <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:         <span class="simpara">            You can insert at the index equal to the number of values.        </span>     </p></blockquote>    </dd>          <dt><span class="parameter" style="color:#3A95FF">values</span></dt>    <dd>     <span class="simpara">        The value or values to insert.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.insert-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    没有返回值。  </p> </div><div class="refsect1 errors" id="refsect1-ds-sequence.insert-errors">  <h3 class="title">错误／异常</h3>  <p class="simpara">   <span class="exceptionname"><a href="https://php.net/manual/zh/class.outofrangeexception.php" class="exceptionname">OutOfRangeException</a></span> if the index is not valid.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.insert-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::insert()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #DD0000">"e"</span><span style="color: #007700">);             </span><span style="color: #FF8000">// [e]<br></span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">"f"</span><span style="color: #007700">);             </span><span style="color: #FF8000">// [e, f]<br></span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">(</span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #DD0000">"g"</span><span style="color: #007700">);             </span><span style="color: #FF8000">// [e, f, g]<br></span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #DD0000">"a"</span><span style="color: #007700">, </span><span style="color: #DD0000">"b"</span><span style="color: #007700">);        </span><span style="color: #FF8000">// [a, b, e, f, g]<br></span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">(</span><span style="color: #9876AA">2</span><span style="color: #007700">, ...[</span><span style="color: #DD0000">"c"</span><span style="color: #007700">, </span><span style="color: #DD0000">"d"</span><span style="color: #007700">]);   </span><span style="color: #FF8000">// [a, b, c, d, e, f, g]<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(Ds\Vector)#1&nbsp;(7)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"a"<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"b"<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"c"<br>&nbsp;&nbsp;[3]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"d"<br>&nbsp;&nbsp;[4]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"e"<br>&nbsp;&nbsp;[5]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"f"<br>&nbsp;&nbsp;[6]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"g"<br>}</blockquote></div>   </div>  </div> </div></div>
 * 
         * Inserts values into the sequence at a given index.
         *
         * @param int $index The index at which to insert. 0 <= index <= count
         * <p><b>Note:</b> You can insert at the index equal to the number of values.</p>
         * @param TValue ...$values The value or values to insert.
         * @throws OutOfRangeException if the index is not valid.
         * @link https://www.php.net/manual/en/ds-sequence.insert.php
         */
        public function insert(int $index, ...$values): void;

        /**
 * <div id="ds-sequence.join" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::join</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::join</span> — <span class="dc-title">Joins all values together as a string</span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.join-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::join</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$glue</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>  <p class="simpara">    Joins all values together as a string using an optional separator between each value.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.join-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">glue</span></dt>    <dd>     <span class="simpara">        An optional string to separate each value.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.join-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    All values of the sequence joined together as a string.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.join-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::join()</strong></span> example using a separator string</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #DD0000">"a"</span><span style="color: #007700">, </span><span style="color: #DD0000">"b"</span><span style="color: #007700">, </span><span style="color: #DD0000">"c"</span><span style="color: #007700">, </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">join</span><span style="color: #007700">(</span><span style="color: #DD0000">"|"</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">string(11)&nbsp;"a|b|c|1|2|3"</blockquote></div>   </div>  </div>  <div class="example" id="example-2"> <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">Ds\Sequence::join()</strong></span> example without a separator string</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #DD0000">"a"</span><span style="color: #007700">, </span><span style="color: #DD0000">"b"</span><span style="color: #007700">, </span><span style="color: #DD0000">"c"</span><span style="color: #007700">, </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">join</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">string(11)&nbsp;"abc123"</blockquote></div>   </div>  </div> </div></div>
 * 
         * Joins all values together as a string using an optional separator
         * between each value.
         * @param string $glue An optional string to separate each value.
         * @return string All values of the sequence joined together as a
         * string.
         * @link https://www.php.net/manual/en/ds-sequence.join.php
         */
        public function join(string $glue = ''): string;

        /**
 * <div id="ds-sequence.last" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::last</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::last</span> — <span class="dc-title">Returns the last value</span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.last-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::last</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>  <p class="simpara">    Returns the last value in the sequence.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.last-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.last-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    The last value in the sequence.  </p> </div> <div class="refsect1 errors" id="refsect1-ds-sequence.last-errors">  <h3 class="title">错误／异常</h3>  <p class="simpara">   <span class="exceptionname"><a href="https://php.net/manual/zh/class.underflowexception.php" class="exceptionname">UnderflowException</a></span> if empty.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.last-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::last()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">last</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(3)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Returns the last value in the sequence.
         * @return TValue The last value in the sequence.
         * @throws UnderflowException if empty.
         * @link https://www.php.net/manual/en/ds-sequence.last.php
         */
        public function last();

        /**
 * <div id="ds-sequence.map" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::map</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::map</span> — <span class="dc-title">Returns the result of applying a callback to each value</span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.map-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::map</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$callback</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-sequence.php" class="type Ds\Sequence" style="color:#EAB766">Ds\Sequence</a></span></div>  <p class="simpara">    Returns the result of applying a <span class="parameter" style="color:#3A95FF">callback</span> function to    each value in the sequence.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.map-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">callback</span></dt>    <dd>        <p class="para">            </p><div class="methodsynopsis dc-description"><span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><span class="replaceable">callback</span></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>                  <span class="simpara">            A <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> to apply to each value in the sequence.         </span>         <span class="simpara">            The callable should return what the new value will be in the new sequence.        </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.map-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    The result of applying a <span class="parameter" style="color:#3A95FF">callback</span> to each value in    the sequence.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     <span class="simpara">        The values of the current instance won't be affected.    </span>  </p></blockquote> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.map-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::map()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">map</span><span style="color: #007700">(function(</span><span style="color: #9876AA">\$value</span><span style="color: #007700">) { return </span><span style="color: #9876AA">\$value </span><span style="color: #007700">* </span><span style="color: #9876AA">2</span><span style="color: #007700">; }));<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Vector&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;2<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;4<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;6<br>)<br>Ds\Vector&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;1<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;2<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;3<br>)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Returns the result of applying a callback function to each value in
         * the sequence.
         * @template TNewValue
         * @param callable(TValue): TNewValue $callback A callable to apply to each value in the
         * sequence.
         * The callable should return what the new value will be in the new
         * sequence.
         * <code>callback ( mixed $value ) : mixed</code>
         * @return Sequence<TNewValue> The result of applying a callback to each value in
         * the sequence.<p><b>Note:</b> The values of the current instance won't be
         * affected.</p>
         * @link https://www.php.net/manual/en/ds-sequence.map.php
         */
        public function map(callable $callback): Sequence;

        /**
 * <div id="ds-sequence.merge" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::merge</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::merge</span> — <span class="dc-title">Returns the result of adding all given values to the sequence</span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.merge-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::merge</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$values</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-sequence.php" class="type Ds\Sequence" style="color:#EAB766">Ds\Sequence</a></span></div>  <p class="simpara">    Returns the result of adding all given values to the sequence.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.merge-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">values</span></dt>    <dd>     <span class="simpara">        A <span class="classname"><a href="https://php.net/manual/zh/class.traversable.php" class="classname">traversable</a></span> object or an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.merge-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    The result of adding all given values to the sequence,    effectively the same as adding the values to a copy, then returning that copy.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     <span class="simpara">        The current instance won't be affected.    </span>  </p></blockquote> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.merge-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::merge()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">merge</span><span style="color: #007700">([</span><span style="color: #9876AA">4</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">, </span><span style="color: #9876AA">6</span><span style="color: #007700">]));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(Ds\Vector)#2&nbsp;(6)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;int(3)<br>&nbsp;&nbsp;[3]=&gt;<br>&nbsp;&nbsp;int(4)<br>&nbsp;&nbsp;[4]=&gt;<br>&nbsp;&nbsp;int(5)<br>&nbsp;&nbsp;[5]=&gt;<br>&nbsp;&nbsp;int(6)<br>}<br>object(Ds\Vector)#1&nbsp;(3)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;int(3)<br>}</blockquote></div>   </div>  </div> </div></div>
 * 
         * Returns the result of adding all given values to the sequence.
         * @template TValue2
         * @param iterable<TValue2> $values A traversable object or an array.
         * @return Sequence<TValue|TValue2> The result of adding all given values to the
         * sequence, effectively the same as adding the values to a copy,
         * then returning that copy.
         * @link https://www.php.net/manual/en/ds-sequence.merge.php
         */
        public function merge($values): Sequence;

        /**
 * <div id="ds-sequence.pop" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::pop</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::pop</span> — <span class="dc-title">Removes and returns the last value</span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.pop-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::pop</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>  <p class="simpara">    Removes and returns the last value.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.pop-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.pop-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    The removed last value.  </p> </div> <div class="refsect1 errors" id="refsect1-ds-sequence.pop-errors">  <h3 class="title">错误／异常</h3>  <p class="simpara">   <span class="exceptionname"><a href="https://php.net/manual/zh/class.underflowexception.php" class="exceptionname">UnderflowException</a></span> if empty.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.pop-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::pop()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">pop</span><span style="color: #007700">());<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">pop</span><span style="color: #007700">());<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">pop</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(3)<br>int(2)<br>int(1)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Removes and returns the last value.
         * @return TValue The removed last value.
         * @throws UnderflowException if empty.
         * @link https://www.php.net/manual/en/ds-sequence.pop.php
         */
        public function pop();

        /**
 * <div id="ds-sequence.push" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::push</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::push</span> — <span class="dc-title">Adds values to the end of the sequence</span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.push-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::push</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">...\$values</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">    Adds values to the end of the sequence.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.push-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">values</span></dt>    <dd>     <span class="simpara">        The values to add.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.push-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    没有返回值。  </p> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.push-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::push()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">push</span><span style="color: #007700">(</span><span style="color: #DD0000">"a"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">push</span><span style="color: #007700">(</span><span style="color: #DD0000">"b"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">push</span><span style="color: #007700">(</span><span style="color: #DD0000">"c"</span><span style="color: #007700">, </span><span style="color: #DD0000">"d"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">push</span><span style="color: #007700">(...[</span><span style="color: #DD0000">"e"</span><span style="color: #007700">, </span><span style="color: #DD0000">"f"</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Vector&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;a<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;b<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;c<br>&nbsp;&nbsp;&nbsp;&nbsp;[3]&nbsp;=&gt;&nbsp;d<br>&nbsp;&nbsp;&nbsp;&nbsp;[4]&nbsp;=&gt;&nbsp;e<br>&nbsp;&nbsp;&nbsp;&nbsp;[5]&nbsp;=&gt;&nbsp;f<br>)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Adds values to the end of the sequence.
         * @param TValue ...$values The values to add.
         */
        public function push(...$values): void;

        /**
 * <div id="ds-sequence.reduce" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::reduce</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::reduce</span> — <span class="dc-title">Reduces the sequence to a single value using a callback function</span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.reduce-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::reduce</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$callback</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$initial</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>  <p class="simpara">    Reduces the sequence to a single value using a callback function.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.reduce-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">callback</span></dt>    <dd>      <div class="methodsynopsis dc-description"><span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><span class="replaceable">callback</span></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$carry</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>      <dl>               <dt><span class="parameter" style="color:#3A95FF">carry</span></dt>        <dd>         <span class="simpara">          The return value of the previous callback, or <span class="parameter" style="color:#3A95FF">initial</span> if          it's the first iteration.         </span>        </dd>                      <dt><span class="parameter" style="color:#3A95FF">value</span></dt>        <dd>         <span class="simpara">          The value of the current iteration.         </span>        </dd>             </dl>     </dd>          <dt><span class="parameter" style="color:#3A95FF">initial</span></dt>    <dd>     <span class="simpara">        The initial value of the carry value. Can be <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.reduce-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    The return value of the final callback.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.reduce-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::reduce()</strong></span> with initial value example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">\$callback </span><span style="color: #007700">= function(</span><span style="color: #9876AA">\$carry</span><span style="color: #007700">, </span><span style="color: #9876AA">\$value</span><span style="color: #007700">) {<br>    return </span><span style="color: #9876AA">\$carry </span><span style="color: #007700">* </span><span style="color: #9876AA">\$value</span><span style="color: #007700">;<br>};<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">reduce</span><span style="color: #007700">(</span><span style="color: #9876AA">\$callback</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">));<br><br></span><span style="color: #FF8000">// Iterations:<br>//<br>// \$carry = \$initial = 5<br>//<br>// \$carry = \$carry * 1 =  5<br>// \$carry = \$carry * 2 = 10<br>// \$carry = \$carry * 3 = 30<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(30)</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">Ds\Sequence::reduce()</strong></span> without an initial value example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">reduce</span><span style="color: #007700">(function(</span><span style="color: #9876AA">\$carry</span><span style="color: #007700">, </span><span style="color: #9876AA">\$value</span><span style="color: #007700">) {<br>    return </span><span style="color: #9876AA">\$carry </span><span style="color: #007700">+ </span><span style="color: #9876AA">\$value </span><span style="color: #007700">+ </span><span style="color: #9876AA">5</span><span style="color: #007700">;<br>}));<br><br></span><span style="color: #FF8000">// Iterations:<br>//<br>// \$carry = \$initial = null<br>//<br>// \$carry = \$carry + 1 + 5 =  6<br>// \$carry = \$carry + 2 + 5 = 13<br>// \$carry = \$carry + 3 + 5 = 21<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(21)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Reduces the sequence to a single value using a callback function.
         * @template TCarry
         * @param callable(TCarry, TValue): TCarry $callback <p>
         * <code>
         * callback ( mixed $carry , mixed $value ) : mixed</code>
         * <b>$carry</b> The return value of the previous callback, or initial if it's
         * the first iteration.<br>
         * <b>$value</b> The value of the current iteration.
         * </p>
         * @param TCarry $initial The initial value of the carry value. Can be NULL.
         * @return TCarry The return value of the final callback.
         * @link https://www.php.net/manual/en/ds-sequence.reduce.php
         */
        public function reduce(callable $callback, $initial = null);

        /**
 * <div id="ds-sequence.remove" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::remove</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::remove</span> — <span class="dc-title">Removes and returns a value by index</span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.remove-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::remove</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$index</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>  <p class="simpara">    Removes and returns a value by index.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.remove-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">index</span></dt>    <dd>     <span class="simpara">        The index of the value to remove.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.remove-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    The value that was removed.  </p> </div> <div class="refsect1 errors" id="refsect1-ds-sequence.remove-errors">  <h3 class="title">错误／异常</h3>  <p class="simpara">   <span class="exceptionname"><a href="https://php.net/manual/zh/class.outofrangeexception.php" class="exceptionname">OutOfRangeException</a></span> if the index is not valid.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.remove-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::remove()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #DD0000">"a"</span><span style="color: #007700">, </span><span style="color: #DD0000">"b"</span><span style="color: #007700">, </span><span style="color: #DD0000">"c"</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">remove</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">remove</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">remove</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">string(1)&nbsp;"b"<br>string(1)&nbsp;"a"<br>string(1)&nbsp;"c"</blockquote></div>   </div>  </div> </div></div>
 * 
         * Removes and returns a value by index.
         * @param int $index The index of the value to remove.
         * @return TValue The value that was removed.
         * @link https://www.php.net/manual/en/ds-sequence.remove.php
         */
        public function remove(int $index);

        /**
 * <div id="ds-sequence.reverse" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::reverse</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::reverse</span> — <span class="dc-title">    Reverses the sequence in-place  </span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.reverse-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::reverse</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">    Reverses the sequence in-place.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.reverse-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.reverse-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    没有返回值。  </p> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.reverse-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::reverse()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #DD0000">"a"</span><span style="color: #007700">, </span><span style="color: #DD0000">"b"</span><span style="color: #007700">, </span><span style="color: #DD0000">"c"</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">reverse</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Vector&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;c<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;b<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;a<br>)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Reverses the sequence in-place.
         * @link https://www.php.net/manual/en/ds-sequence.reverse.php
         */
        public function reverse(): void;

        /**
 * <div id="ds-sequence.reversed" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::reversed</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::reversed</span> — <span class="dc-title">Returns a reversed copy</span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.reversed-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::reversed</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-sequence.php" class="type Ds\Sequence" style="color:#EAB766">Ds\Sequence</a></span></div>  <p class="simpara">    Returns a reversed copy of the sequence.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.reversed-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.reversed-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    A reversed copy of the sequence.    </p><blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:         <span class="simpara">            The current instance is not affected.        </span>    </p></blockquote>   </div> <div class="refsect1 examples" id="refsect1-ds-sequence.reversed-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::reversed()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #DD0000">"a"</span><span style="color: #007700">, </span><span style="color: #DD0000">"b"</span><span style="color: #007700">, </span><span style="color: #DD0000">"c"</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">reversed</span><span style="color: #007700">());<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Vector&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;c<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;b<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;a<br>)<br>Ds\Vector&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;a<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;b<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;c<br>)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Returns a reversed copy of the sequence.
         * @return Sequence<TValue> A reversed copy of the sequence.
         * <p><b>Note:</b> The current instance is not affected.</p>
         */
        public function reversed();

        /**
 * <div id="ds-sequence.rotate" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::rotate</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::rotate</span> — <span class="dc-title">Rotates the sequence by a given number of rotations</span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.rotate-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::rotate</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$rotations</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">    Rotates the sequence by a given number of rotations, which is equivalent    to successively calling <span class="code">\$sequence-&gt;push(\$sequence-&gt;shift())</span> if the number    of rotations is positive, or <span class="code">\$sequence-&gt;unshift(\$sequence-&gt;pop())</span> if negative.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.rotate-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">rotations</span></dt>    <dd>     <span class="simpara">        The number of times the sequence should be rotated.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.rotate-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    没有返回值。. The sequence of the current instance will be rotated.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.rotate-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::rotate()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #DD0000">"a"</span><span style="color: #007700">, </span><span style="color: #DD0000">"b"</span><span style="color: #007700">, </span><span style="color: #DD0000">"c"</span><span style="color: #007700">, </span><span style="color: #DD0000">"d"</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">rotate</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">);  </span><span style="color: #FF8000">// "a" is shifted, then pushed.<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">rotate</span><span style="color: #007700">(</span><span style="color: #9876AA">2</span><span style="color: #007700">);  </span><span style="color: #FF8000">// "b" and "c" are both shifted, then pushed.<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;b<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;c<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;d<br>&nbsp;&nbsp;&nbsp;&nbsp;[3]&nbsp;=&gt;&nbsp;a<br>)<br>Ds\Vector&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;d<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;a<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;b<br>&nbsp;&nbsp;&nbsp;&nbsp;[3]&nbsp;=&gt;&nbsp;c<br>)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Rotates the sequence by a given number of rotations, which is
         * equivalent to successively calling
         * $sequence->push($sequence->shift()) if the number of rotations is
         * positive, or $sequence->unshift($sequence->pop()) if negative.
         * @param int $rotations The number of times the sequence should be
         * rotated.
         * @link https://www.php.net/manual/en/ds-sequence.rotate.php
         */
        public function rotate(int $rotations): void;

        /**
 * <div id="ds-sequence.set" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::set</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::set</span> — <span class="dc-title">Updates a value at a given index</span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.set-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::set</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$index</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">    Updates a value at a given index.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.set-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">index</span></dt>    <dd>     <span class="simpara">        The index of the value to update.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">value</span></dt>    <dd>     <span class="simpara">        The new value.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.set-returnvalues">    <h3 class="title">返回值</h3>    <p class="simpara">        没有返回值。    </p> </div> <div class="refsect1 errors" id="refsect1-ds-sequence.set-errors">  <h3 class="title">错误／异常</h3>  <p class="simpara">   <span class="exceptionname"><a href="https://php.net/manual/zh/class.outofrangeexception.php" class="exceptionname">OutOfRangeException</a></span> if the index is not valid.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.set-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::set()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #DD0000">"a"</span><span style="color: #007700">, </span><span style="color: #DD0000">"b"</span><span style="color: #007700">, </span><span style="color: #DD0000">"c"</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">set</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">"_"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Vector&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;a<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;_<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;c<br>)</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">Ds\Sequence::set()</strong></span> example using array syntax</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #DD0000">"a"</span><span style="color: #007700">, </span><span style="color: #DD0000">"b"</span><span style="color: #007700">, </span><span style="color: #DD0000">"c"</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">[</span><span style="color: #9876AA">1</span><span style="color: #007700">] = </span><span style="color: #DD0000">"_"</span><span style="color: #007700">;<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Vector&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;a<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;_<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;c<br>)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Updates a value at a given index.
         * @param int $index The index of the value to update.
         * @param TValue $value The new value.
         * @throws OutOfRangeException if the index is not valid.
         * @link https://www.php.net/manual/en/ds-sequence.set.php
         */
        public function set(int $index, $value): void;

        /**
 * <div id="ds-sequence.shift" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::shift</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::shift</span> — <span class="dc-title">Removes and returns the first value</span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.shift-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::shift</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>  <p class="simpara">    Removes and returns the first value.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.shift-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.shift-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    The first value, which was removed.  </p> </div> <div class="refsect1 errors" id="refsect1-ds-sequence.shift-errors">  <h3 class="title">错误／异常</h3>  <p class="simpara">   <span class="exceptionname"><a href="https://php.net/manual/zh/class.underflowexception.php" class="exceptionname">UnderflowException</a></span> if empty.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.shift-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::shift()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #DD0000">"a"</span><span style="color: #007700">, </span><span style="color: #DD0000">"b"</span><span style="color: #007700">, </span><span style="color: #DD0000">"c"</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">shift</span><span style="color: #007700">());<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">shift</span><span style="color: #007700">());<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">shift</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">string(1)&nbsp;"a"<br>string(1)&nbsp;"b"<br>string(1)&nbsp;"c"</blockquote></div>   </div>  </div> </div></div>
 * 
         * Removes and returns the first value.
         * @return TValue
         * @throws UnderflowException if empty.
         * @link https://www.php.net/manual/en/ds-sequence.shift.php
         */
        public function shift();

        /**
 * <div id="ds-sequence.slice" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::slice</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::slice</span> — <span class="dc-title">   Returns a sub-sequence of a given range  </span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.slice-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::slice</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$index</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$length</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-sequence.php" class="type Ds\Sequence" style="color:#EAB766">Ds\Sequence</a></span></div>  <p class="simpara">    Creates a sub-sequence of a given range.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.slice-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">index</span></dt>    <dd>        <span class="simpara">            The index at which the sub-sequence starts.        </span>        <span class="simpara">            If positive, the sequence will start at that index in the sequence.            If negative, the sequence will start that far from the end.        </span>    </dd>            <dt><span class="parameter" style="color:#3A95FF">length</span></dt>    <dd>     <span class="simpara">        If a length is given and is positive, the resulting        sequence will have up to that many values in it.        If the length results in an overflow, only        values up to the end of the sequence will be included.        If a length is given and is negative, the sequence        will stop that many values from the end.        If a length is not provided, the resulting sequence        will contain all values between the index and the        end of the sequence.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.slice-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    A sub-sequence of the given range.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.slice-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::slice()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #DD0000">"a"</span><span style="color: #007700">, </span><span style="color: #DD0000">"b"</span><span style="color: #007700">, </span><span style="color: #DD0000">"c"</span><span style="color: #007700">, </span><span style="color: #DD0000">"d"</span><span style="color: #007700">, </span><span style="color: #DD0000">"e"</span><span style="color: #007700">]);<br><br></span><span style="color: #FF8000">// Slice from 2 onwards<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">slice</span><span style="color: #007700">(</span><span style="color: #9876AA">2</span><span style="color: #007700">));<br><br></span><span style="color: #FF8000">// Slice from 1, for a length of 3<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">slice</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">));<br><br></span><span style="color: #FF8000">// Slice from 1 onwards<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">slice</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">));<br><br></span><span style="color: #FF8000">// Slice from 2 from the end onwards<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">slice</span><span style="color: #007700">(-</span><span style="color: #9876AA">2</span><span style="color: #007700">));<br><br></span><span style="color: #FF8000">// Slice from 1 to 1 from the end<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">slice</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">, -</span><span style="color: #9876AA">1</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Vector&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;c<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;d<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;e<br>)<br>Ds\Vector&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;b<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;c<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;d<br>)<br>Ds\Vector&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;b<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;c<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;d<br>&nbsp;&nbsp;&nbsp;&nbsp;[3]&nbsp;=&gt;&nbsp;e<br>)<br>Ds\Vector&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;d<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;e<br>)<br>Ds\Vector&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;b<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;c<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;d<br>)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Creates a sub-sequence of a given range.
         * @param int $index The index at which the sub-sequence starts.
         * If positive, the sequence will start at that index in the sequence.
         * If negative, the sequence will start that far from the end.
         * @param int|null $length If a length is given and is positive, the
         * resulting sequence will have up to that many values in it. If the
         * length results in an overflow, only values up to the end of the
         * sequence will be included. If a length is given and is negative,
         * the sequence will stop that many values from the end. If a length
         * is not provided, the resulting sequence will contain all values
         * between the index and the end of the sequence.
         * @return Sequence<TValue> A sub-sequence of the given range.
         * @link https://www.php.net/manual/en/ds-sequence.slice.php
         */
        public function slice(int $index, ?int $length = null);

        /**
 * <div id="ds-sequence.sort" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::sort</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::sort</span> — <span class="dc-title">    Sorts the sequence in-place </span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.sort-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::sort</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$comparator</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">    Sorts the sequence in-place, using an optional <span class="parameter" style="color:#3A95FF">comparator</span> function.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.sort-parameters">  <h3 class="title">参数</h3>  <dl>        <dt><span class="parameter" style="color:#3A95FF">comparator</span></dt>     <dd>      <span class="simpara"> 在第一个参数小于，等于或大于第二个参数时，该比较函数必须相应地返回一个小于，等于或大于 0 的整数。</span><div class="methodsynopsis dc-description"><span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><span class="replaceable">callback</span></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$a</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$b</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div><div class="caution"><strong class="caution">警告</strong> <p class="simpara">  从比较函数中返回<em>非整数</em>值，例如 <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.float.php" class="type float" style="color:#EAB766">float</a></span>，将导致内部强制转换为 callback 返回值为  <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>。因此，诸如 <span class="literal">0.99</span> 和 <span class="literal">0.1</span> 之类的值都将被转换为整数值  <span class="literal">0</span>，将这些值比较的话将会是相等。 </p></div>     </dd>      </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.sort-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    没有返回值。  </p> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.sort-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::sort()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #9876AA">4</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">, </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sort</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Vector&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;1<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;2<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;3<br>&nbsp;&nbsp;&nbsp;&nbsp;[3]&nbsp;=&gt;&nbsp;4<br>&nbsp;&nbsp;&nbsp;&nbsp;[4]&nbsp;=&gt;&nbsp;5<br>)</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">Ds\Sequence::sort()</strong></span> example using a comparator</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #9876AA">4</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">, </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sort</span><span style="color: #007700">(function(</span><span style="color: #9876AA">\$a</span><span style="color: #007700">, </span><span style="color: #9876AA">\$b</span><span style="color: #007700">) {<br>    return </span><span style="color: #9876AA">\$b </span><span style="color: #007700">&lt;=&gt; </span><span style="color: #9876AA">\$a</span><span style="color: #007700">;<br>});<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Vector&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;5<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;4<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;3<br>&nbsp;&nbsp;&nbsp;&nbsp;[3]&nbsp;=&gt;&nbsp;2<br>&nbsp;&nbsp;&nbsp;&nbsp;[4]&nbsp;=&gt;&nbsp;1<br>)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Sorts the sequence in-place, using an optional comparator function.
         * @param (callable(TValue, TValue): int)|null $comparator The comparison function must return
         * an integer less than, equal to, or greater than zero if the first
         * argument is considered to be respectively less than, equal to, or
         * greater than the second. Note that before PHP 7.0.0 this integer had
         * to be in the range from -2147483648 to 2147483647.<p>
         * <code>callback ( mixed $a, mixed $b ) : int</code></p>
         * <p><b>Caution:</b> Returning non-integer values from the comparison
         * function, such as float, will result in an internal cast to integer
         * of the callback's return value. So values such as 0.99 and 0.1 will
         * both be cast to an integer value of 0, which will compare such
         * values as equal.</p>
         * @link https://www.php.net/manual/en/ds-sequence.sort.php
         */
        public function sort(?callable $comparator = null): void;

        /**
 * <div id="ds-sequence.sorted" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::sorted</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::sorted</span> — <span class="dc-title">Returns a sorted copy</span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.sorted-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::sorted</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$comparator</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-sequence.php" class="type Ds\Sequence" style="color:#EAB766">Ds\Sequence</a></span></div>  <p class="simpara">    Returns a sorted copy, using an optional <span class="parameter" style="color:#3A95FF">comparator</span> function.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.sorted-parameters">  <h3 class="title">参数</h3>  <dl>        <dt><span class="parameter" style="color:#3A95FF">comparator</span></dt>     <dd>      <span class="simpara"> 在第一个参数小于，等于或大于第二个参数时，该比较函数必须相应地返回一个小于，等于或大于 0 的整数。</span><div class="methodsynopsis dc-description"><span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><span class="replaceable">callback</span></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$a</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$b</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div><div class="caution"><strong class="caution">警告</strong> <p class="simpara">  从比较函数中返回<em>非整数</em>值，例如 <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.float.php" class="type float" style="color:#EAB766">float</a></span>，将导致内部强制转换为 callback 返回值为  <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>。因此，诸如 <span class="literal">0.99</span> 和 <span class="literal">0.1</span> 之类的值都将被转换为整数值  <span class="literal">0</span>，将这些值比较的话将会是相等。 </p></div>     </dd>      </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.sorted-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    Returns a sorted copy of the sequence.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.sorted-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::sorted()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #9876AA">4</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">, </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sorted</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Vector&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;1<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;2<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;3<br>&nbsp;&nbsp;&nbsp;&nbsp;[3]&nbsp;=&gt;&nbsp;4<br>&nbsp;&nbsp;&nbsp;&nbsp;[4]&nbsp;=&gt;&nbsp;5<br>)</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">Ds\Sequence::sorted()</strong></span> example using a comparator</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #9876AA">4</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">, </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">\$sorted </span><span style="color: #007700">= </span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sorted</span><span style="color: #007700">(function(</span><span style="color: #9876AA">\$a</span><span style="color: #007700">, </span><span style="color: #9876AA">\$b</span><span style="color: #007700">) {<br>    return </span><span style="color: #9876AA">\$b </span><span style="color: #007700">&lt;=&gt; </span><span style="color: #9876AA">\$a</span><span style="color: #007700">;<br>});<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sorted</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Vector&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;5<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;4<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;3<br>&nbsp;&nbsp;&nbsp;&nbsp;[3]&nbsp;=&gt;&nbsp;2<br>&nbsp;&nbsp;&nbsp;&nbsp;[4]&nbsp;=&gt;&nbsp;1<br>)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Returns a sorted copy, using an optional comparator function.
         * @param (callable(TValue, TValue): int)|null $comparator The comparison function must return
         * an integer less than, equal to, or greater than zero if the first
         * argument is considered to be respectively less than, equal to, or
         * greater than the second. Note that before PHP 7.0.0 this integer had
         * to be in the range from -2147483648 to 2147483647.<p>
         * <code>callback ( mixed $a, mixed $b ) : int</code></p>
         * <p><b>Caution:</b> Returning non-integer values from the comparison
         * function, such as float, will result in an internal cast to integer
         * of the callback's return value. So values such as 0.99 and 0.1 will
         * both be cast to an integer value of 0, which will compare such
         * values as equal.</p>
         * @return Sequence<TValue> Returns a sorted copy of the sequence.
         * @link https://www.php.net/manual/en/ds-sequence.sort.php
         */
        public function sorted(?callable $comparator = null);

        /**
 * <div id="ds-sequence.sum" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::sum</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::sum</span> — <span class="dc-title">Returns the sum of all values in the sequence</span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.sum-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::sum</strong></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.float.php" class="type float" style="color:#EAB766">float</a></span></span></div>  <p class="simpara">    Returns the sum of all values in the sequence.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     <span class="simpara">        Arrays and objects are considered equal to zero when calculating the sum.    </span>  </p></blockquote> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.sum-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.sum-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    The sum of all the values in the sequence as either a <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.float.php" class="type float" style="color:#EAB766">float</a></span> or <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>    depending on the values in the sequence.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.sum-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::sum()</strong></span> integer example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sum</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(6)</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">Ds\Sequence::sum()</strong></span> float example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2.5</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sum</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">float(6.5)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Returns the sum of all values in the sequence.
         * <p><b>Note:</b> Arrays and objects are considered equal to zero when
         * calculating the sum.</p>
         * @return float|int The sum of all the values in the sequence as
         * either a float or int depending on the values in the sequence.
         */
        public function sum(): float|int;

        /**
 * <div id="ds-sequence.unshift" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Sequence::unshift</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Sequence::unshift</span> — <span class="dc-title">Adds values to the front of the sequence</span></p> </div> <div class="refsect1 description" id="refsect1-ds-sequence.unshift-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Sequence::unshift</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$values</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">    Adds values to the front of the sequence, moving all the current    values forward to make room for the new values.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-sequence.unshift-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">values</span></dt>    <dd>     <p class="para">        The values to add to the front of the sequence.        </p><blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:             <span class="simpara">                Multiple values will be added in the same order that they are                passed.            </span>        </p></blockquote>         </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-sequence.unshift-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    没有返回值。  </p> </div> <div class="refsect1 examples" id="refsect1-ds-sequence.unshift-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Sequence::unshift()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$sequence </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Vector</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">unshift</span><span style="color: #007700">(</span><span style="color: #DD0000">"a"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">unshift</span><span style="color: #007700">(</span><span style="color: #DD0000">"b"</span><span style="color: #007700">, </span><span style="color: #DD0000">"c"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sequence</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Vector&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;b<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;c<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;a<br>&nbsp;&nbsp;&nbsp;&nbsp;[3]&nbsp;=&gt;&nbsp;1<br>&nbsp;&nbsp;&nbsp;&nbsp;[4]&nbsp;=&gt;&nbsp;2<br>&nbsp;&nbsp;&nbsp;&nbsp;[5]&nbsp;=&gt;&nbsp;3<br>)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Adds values to the front of the sequence, moving all the current
         * values forward to make room for the new values.
         * @param TValue ...$values The values to add to the front of the sequence.
         * <p><b>Note:</b> Multiple values will be added in the same order that they
         * are passed.</p>
         */
        public function unshift(...$values): void;
    }

    /**
 * <div id="class.ds-vector" class="reference"> <h1 class="title">The Vector class</h1>  <div class="partintro"><p class="verinfo">(PECL ds &gt;= 1.0.0)</p>  <div class="section" id="ds-vector.intro">   <h2 class="title">简介</h2>   <p class="para">    A Vector is a sequence of values in a contiguous buffer that grows and    shrinks automatically. It’s the most efficient sequential structure because    a value’s index is a direct mapping to its index in the buffer, and the    growth factor isn't bound to a specific multiple or exponent.   </p>  </div><div class="section" id="ds-vector.strengths">    <h2 class="title">Strengths</h2>    <p class="para">        </p><ul class="simplelist">            <li>Supports array syntax (square brackets).</li>            <li>Uses less overall memory than an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> for the same number of values.</li>            <li>Automatically frees allocated memory when its size drops low enough.</li>            <li>Capacity does not have to be a power of 2.</li>            <li>                <span class="function"><strong style="color:#CC7832">get()</strong></span>,                <span class="function"><strong style="color:#CC7832">set()</strong></span>,                <span class="function"><strong style="color:#CC7832">push()</strong></span>,                <span class="function"><strong style="color:#CC7832">pop()</strong></span> are all O(1).            </li>        </ul>   </div><div class="section" id="ds-vector.weaknesses">    <h2 class="title">Weaknesses</h2>    <p class="para">        </p><ul class="simplelist">            <li>                <span class="function"><strong style="color:#CC7832">shift()</strong></span>,                <span class="function"><strong style="color:#CC7832">unshift()</strong></span>,                <span class="function"><strong style="color:#CC7832">insert()</strong></span> and                <span class="function"><strong style="color:#CC7832">remove()</strong></span> are all O(n).            </li>        </ul>   </div>  <div class="section" id="ds-vector.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass">        <strong class="classname"></strong>    </span>    <div class="classsynopsisinfo">    <span class="ooclass"><span class="modifier">class</span> <strong class="classname">Ds\Vector</strong></span>    <span class="oointerface"><span class="modifier">implements</span>  <a href="https://php.net/manual/zh/class.ds-sequence.php" class="interfacename">Ds\Sequence</a></span><span class="oointerface">,  <a href="https://php.net/manual/zh/class.arrayaccess.php" class="interfacename">ArrayAccess</a></span> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 常量 </div>    <div class="fieldsynopsis">     <span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.ds-vector.php#ds-vector.constants.min-capacity"><var class="varname">MIN_CAPACITY</var></a></var><span class="initializer"> = 8</span>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-vector.allocate.php" class="methodname" style="color:#CC7832">allocate</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$capacity</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-vector.apply.php" class="methodname" style="color:#CC7832">apply</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$callback</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-vector.capacity.php" class="methodname" style="color:#CC7832">capacity</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-vector.clear.php" class="methodname" style="color:#CC7832">clear</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-vector.contains.php" class="methodname" style="color:#CC7832