        public function push(...$values): void {}

        /**
 * <div id="ds-deque.reduce" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Deque::reduce</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Deque::reduce</span> — <span class="dc-title">Reduces the deque to a single value using a callback function</span></p> </div> <div class="refsect1 description" id="refsect1-ds-deque.reduce-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Deque::reduce</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$callback</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$initial</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>  <p class="para rdfs-comment">    Reduces the deque to a single value using a callback function.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-deque.reduce-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">callback</span></dt>    <dd>      <div class="methodsynopsis dc-description"><span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><span class="replaceable">callback</span></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$carry</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>      <dl>               <dt><span class="parameter" style="color:#3A95FF">carry</span></dt>        <dd>         <p class="para">          The return value of the previous callback, or <span class="parameter" style="color:#3A95FF">initial</span> if          it's the first iteration.         </p>        </dd>                      <dt><span class="parameter" style="color:#3A95FF">value</span></dt>        <dd>         <p class="para">          The value of the current iteration.         </p>        </dd>             </dl>     </dd>          <dt><span class="parameter" style="color:#3A95FF">initial</span></dt>    <dd>     <p class="para">        The initial value of the carry value. Can be <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-deque.reduce-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    The return value of the final callback.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-deque.reduce-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Deque::reduce()</strong></span> with initial value example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$deque </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Deque</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">\$callback </span><span style="color: #007700">= function(</span><span style="color: #9876AA">\$carry</span><span style="color: #007700">, </span><span style="color: #9876AA">\$value</span><span style="color: #007700">) {<br>    return </span><span style="color: #9876AA">\$carry </span><span style="color: #007700">* </span><span style="color: #9876AA">\$value</span><span style="color: #007700">;<br>};<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$deque</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">reduce</span><span style="color: #007700">(</span><span style="color: #9876AA">\$callback</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">));<br><br></span><span style="color: #FF8000">// Iterations:<br>//<br>// \$carry = \$initial = 5<br>//<br>// \$carry = \$carry * 1 =  5<br>// \$carry = \$carry * 2 = 10<br>// \$carry = \$carry * 3 = 30<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(30)</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">Ds\Deque::reduce()</strong></span> without an initial value example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$deque </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Deque</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$deque</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">reduce</span><span style="color: #007700">(function(</span><span style="color: #9876AA">\$carry</span><span style="color: #007700">, </span><span style="color: #9876AA">\$value</span><span style="color: #007700">) {<br>    return </span><span style="color: #9876AA">\$carry </span><span style="color: #007700">+ </span><span style="color: #9876AA">\$value </span><span style="color: #007700">+ </span><span style="color: #9876AA">5</span><span style="color: #007700">;<br>}));<br><br></span><span style="color: #FF8000">// Iterations:<br>//<br>// \$carry = \$initial = null<br>//<br>// \$carry = \$carry + 1 + 5 =  6<br>// \$carry = \$carry + 2 + 5 = 13<br>// \$carry = \$carry + 3 + 5 = 21<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(21)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Reduces the deque to a single value using a callback function.
         * @template TCarry
         * @param callable(TCarry, TValue): TCarry $callback
         * <code>callback ( mixed $carry , mixed $value ) : mixed</code>
         * <b>$carry</b> The return value of the previous callback, or initial if it's
         * the first iteration.<p>
         * <b>$value</b> The value of the current iteration.
         * </p>
         * @param TCarry $initial The initial value of the carry value. Can be NULL.
         * @return TCarry The return value of the final callback.
         * @link https://www.php.net/manual/en/ds-deque.reduce.php
         */
        public function reduce(callable $callback, $initial = null) {}

        /**
 * <div id="ds-deque.remove" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Deque::remove</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Deque::remove</span> — <span class="dc-title">Removes and returns a value by index</span></p> </div> <div class="refsect1 description" id="refsect1-ds-deque.remove-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Deque::remove</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$index</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>  <p class="para rdfs-comment">    Removes and returns a value by index.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-deque.remove-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">index</span></dt>    <dd>     <p class="para">        The index of the value to remove.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-deque.remove-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    The value that was removed.  </p> </div> <div class="refsect1 errors" id="refsect1-ds-deque.remove-errors">  <h3 class="title">错误／异常</h3>  <p class="para">   <span class="classname"><a href="https://php.net/manual/zh/class.outofrangeexception.php" class="classname">OutOfRangeException</a></span> if the index is not valid.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-deque.remove-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Deque::remove()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$deque </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Deque</span><span style="color: #007700">([</span><span style="color: #DD0000">"a"</span><span style="color: #007700">, </span><span style="color: #DD0000">"b"</span><span style="color: #007700">, </span><span style="color: #DD0000">"c"</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$deque</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">remove</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$deque</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">remove</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$deque</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">remove</span><span style="color: #007700">(</span><span style="color: #9876AA">0</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">string(1)&nbsp;"b"<br>string(1)&nbsp;"a"<br>string(1)&nbsp;"c"</blockquote></div>   </div>  </div> </div></div>
 * 
         * Removes and returns a value by index.
         * @param int $index The index of the value to remove.
         * @return TValue The value that was removed.
         * @link https://www.php.net/manual/en/ds-deque.remove.php
         */
        public function remove(int $index) {}

        /**
 * <div id="ds-deque.reverse" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Deque::reverse</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Deque::reverse</span> — <span class="dc-title">    Reverses the deque in-place  </span></p> </div> <div class="refsect1 description" id="refsect1-ds-deque.reverse-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Deque::reverse</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">    Reverses the deque in-place.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-deque.reverse-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-deque.reverse-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    没有返回值。  </p> </div> <div class="refsect1 examples" id="refsect1-ds-deque.reverse-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Deque::reverse()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$deque </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Deque</span><span style="color: #007700">([</span><span style="color: #DD0000">"a"</span><span style="color: #007700">, </span><span style="color: #DD0000">"b"</span><span style="color: #007700">, </span><span style="color: #DD0000">"c"</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$deque</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">reverse</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$deque</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Deque&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;c<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;b<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;a<br>)</blockquote></div>   </div>  </div> </div></div>
