    /**
 * <div id="class.ds-queue" class="reference"> <h1 class="title">The Queue class</h1>  <div class="partintro"><p class="verinfo">(PECL ds &gt;= 1.0.0)</p>  <div class="section" id="ds-queue.intro">   <h2 class="title">简介</h2>   <p class="para">    A Queue is a “first in, first out” or “FIFO” collection that only allows    access to the value at the front of the queue and iterates in that order,    destructively.   </p>  </div>  <div class="section" id="ds-queue.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">Ds\Queue</strong>     </span>     <span class="oointerface"><span class="modifier">implements</span>        <a href="https://php.net/manual/zh/class.ds-collection.php" class="interfacename">Ds\Collection</a></span><span class="oointerface">,  <a href="https://php.net/manual/zh/class.arrayaccess.php" class="interfacename">ArrayAccess</a></span> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 常量 </div>    <div class="fieldsynopsis">     <span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.ds-queue.php#ds-queue.constants.min-capacity"><var class="varname">MIN_CAPACITY</var></a></var><span class="initializer"> = 8</span>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-queue.allocate.php" class="methodname" style="color:#CC7832">allocate</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$capacity</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-queue.capacity.php" class="methodname" style="color:#CC7832">capacity</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-queue.clear.php" class="methodname" style="color:#CC7832">clear</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-queue.copy.php" class="methodname" style="color:#CC7832">copy</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-queue.php" class="type Ds\Queue" style="color:#EAB766">Ds\Queue</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-queue.isempty.php" class="methodname" style="color:#CC7832">isEmpty</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-queue.peek.php" class="methodname" style="color:#CC7832">peek</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-queue.pop.php" class="methodname" style="color:#CC7832">pop</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-queue.push.php" class="methodname" style="color:#CC7832">push</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">...\$values</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-queue.toarray.php" class="methodname" style="color:#CC7832">toArray</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>   }</div>  </div>  <div class="section" id="ds-queue.constants">   <h2 class="title">预定义常量</h2>   <dl>         <dt id="ds-queue.constants.min-capacity"><strong><span>{@link Ds\Queue::MIN_CAPACITY}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>       </dl>  </div>  <div class="section">   <h2 class="title">更新日志</h2>   <p class="para">    </p><table class="doctable informaltable">           <thead>       <tr>        <th>版本</th>        <th>说明</th>       </tr>      </thead>      <tbody class="tbody">       <tr>        <td>PECL ds 1.3.0</td>        <td>         The class now implements <span class="classname"><a href="https://php.net/manual/zh/class.arrayaccess.php" class="classname">ArrayAccess</a></span>.        </td>       </tr>      </tbody>         </table>     </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link Ds\Queue::allocate} — Allocates enough memory for a required capacity</li><li>{@link Ds\Queue::capacity} — Returns the current capacity</li><li>{@link Ds\Queue::clear} — Removes all values</li><li>{@link Ds\Queue::__construct} — Creates a new instance</li><li>{@link Ds\Queue::copy} — Returns a shallow copy of the queue</li><li>{@link Ds\Queue::count} — Returns the number of values in the queue</li><li>{@link Ds\Queue::isEmpty} — Returns whether the queue is empty</li><li>{@link Ds\Queue::jsonSerialize} — Returns a representation that can be converted to JSON</li><li>{@link Ds\Queue::peek} — Returns the value at the front of the queue</li><li>{@link Ds\Queue::pop} — Removes and returns the value at the front of the queue</li><li>{@link Ds\Queue::push} — Pushes values into the queue</li><li>{@link Ds\Queue::toArray} — Converts the queue to an array</li></ul></div>
 * 
     * A Queue is a “first in, first out” or “FIFO” collection that only allows
     * access to the value at the front of the queue and iterates in that order,
     * destructively.
     *
     * Uses a Ds\Vector internally.
     *
     * @package Ds
     * @template TValue
     * @implements Collection<int, TValue>
     */
    final class Queue implements Collection, ArrayAccess
    {
        /**
 * <div id="ds-queue.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Queue::__construct</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Queue::__construct</span> — <span class="dc-title">Creates a new instance</span></p> </div> <div class="refsect1 description" id="refsect1-ds-queue.construct-description">  <h3 class="title">说明</h3>  <div class="constructorsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Queue::__construct</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$values</span><span class="initializer"> = ?</span></span>)</div>  <p class="para rdfs-comment">    Creates a new instance, using either a <span class="classname"><a href="https://php.net/manual/zh/class.traversable.php" class="classname">traversable</a></span>    object or an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> for the initial <span class="parameter" style="color:#3A95FF">values</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-queue.construct-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">values</span></dt>    <dd>     <p class="para">      A traversable object or an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> to use for the initial values.     </p>    </dd>     </dl> </div>  <div class="refsect1 examples" id="refsect1-ds-queue.construct-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Queue::__construct()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$queue </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Queue</span><span style="color: #007700">();<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$queue</span><span style="color: #007700">);<br><br><br></span><span style="color: #9876AA">\$queue </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Queue</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$queue</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(Ds\Queue)#2&nbsp;(0)&nbsp;{<br>}<br>object(Ds\Queue)#2&nbsp;(3)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;int(3)<br>}</blockquote></div>   </div>  </div> </div></div>
