    }

    /**
 * <div id="class.ds-priorityqueue" class="reference"> <h1 class="title">The PriorityQueue class</h1>  <div class="partintro"><p class="verinfo">(PECL ds &gt;= 1.0.0)</p>  <div class="section" id="ds-priorityqueue.intro">   <h2 class="title">简介</h2>   <p class="para">    A PriorityQueue is very similar to a Queue. Values are pushed into the queue    with an assigned priority, and the value with the highest priority will    always be at the front of the queue.   </p>   <p class="para">        Implemented using a max heap.   </p>   <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:         </p><p class="para">            "First in, first out" ordering is preserved for values with the same priority.        </p>   </blockquote>   <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:         </p><p class="para">            Iterating over a PriorityQueue is destructive, equivalent to successive pop operations until the queue is empty.        </p>   </blockquote>  </div>  <div class="section" id="ds-priorityqueue.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">Ds\PriorityQueue</strong>     </span>     <span class="oointerface"><span class="modifier">implements</span>        <a href="https://php.net/manual/zh/class.ds-collection.php" class="interfacename">Ds\Collection</a></span> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 常量 </div>    <div class="fieldsynopsis">     <span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.ds-priorityqueue.php#ds-priorityqueue.constants.min-capacity"><var class="varname">MIN_CAPACITY</var></a></var><span class="initializer"> = 8</span>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-priorityqueue.allocate.php" class="methodname" style="color:#CC7832">allocate</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$capacity</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-priorityqueue.capacity.php" class="methodname" style="color:#CC7832">capacity</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-priorityqueue.clear.php" class="methodname" style="color:#CC7832">clear</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-priorityqueue.copy.php" class="methodname" style="color:#CC7832">copy</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-priorityqueue.php" class="type Ds\PriorityQueue" style="color:#EAB766">Ds\PriorityQueue</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-priorityqueue.isempty.php" class="methodname" style="color:#CC7832">isEmpty</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-priorityqueue.peek.php" class="methodname" style="color:#CC7832">peek</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-priorityqueue.pop.php" class="methodname" style="color:#CC7832">pop</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-priorityqueue.push.php" class="methodname" style="color:#CC7832">push</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$priority</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-priorityqueue.toarray.php" class="methodname" style="color:#CC7832">toArray</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>   }</div>  </div>  <div class="section" id="ds-priorityqueue.constants">   <h2 class="title">预定义常量</h2>   <dl>         <dt id="ds-priorityqueue.constants.min-capacity"><strong><span>{@link Ds\PriorityQueue::MIN_CAPACITY}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>       </dl>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link Ds\PriorityQueue::allocate} — Allocates enough memory for a required capacity</li><li>{@link Ds\PriorityQueue::capacity} — Returns the current capacity</li><li>{@link Ds\PriorityQueue::clear} — Removes all values</li><li>{@link Ds\PriorityQueue::__construct} — Creates a new instance</li><li>{@link Ds\PriorityQueue::copy} — Returns a shallow copy of the queue</li><li>{@link Ds\PriorityQueue::count} — Returns the number of values in the queue</li><li>{@link Ds\PriorityQueue::isEmpty} — Returns whether the queue is empty</li><li>{@link Ds\PriorityQueue::jsonSerialize} — Returns a representation that can be converted to JSON</li><li>{@link Ds\PriorityQueue::peek} — Returns the value at the front of the queue</li><li>{@link Ds\PriorityQueue::pop} — Removes and returns the value with the highest priority</li><li>{@link Ds\PriorityQueue::push} — Pushes values into the queue</li><li>{@link Ds\PriorityQueue::toArray} — Converts the queue to an array</li></ul></div>
 * 
     * A PriorityQueue is very similar to a Queue. Values are pushed into the
     * queue with an assigned priority, and the value with the highest priority
     * will always be at the front of the queue.
     *
     * Implemented using a max heap.
     *
     * @package Ds
     * @template TValue
     * @implements Collection<int, TValue>
     *
     * @link https://www.php.net/manual/en/class.ds-priorityqueue.php
     */
    final class PriorityQueue implements Collection
    {
        public const MIN_CAPACITY = 8;

        /**
 * <div id="ds-priorityqueue.count" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\PriorityQueue::count</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\PriorityQueue::count</span> — <span class="dc-title">Returns the number of values in the queue</span></p> </div> <div class="refsect1 description" id="refsect1-ds-priorityqueue.count-description">  <h3 class="title">说明</h3>  <p class="para">   See <span class="function">{@link Countable::count()}</span>  </p> </div></div>
 * 
         * Count elements of an object
         * @link https://php.net/manual/zh/countable.count.php
         * @return int The custom count as an integer.
         * </p>
         * <p>
         * The return value is cast to an integer.
         * @since 5.1
         */
        public function count(): int {}

        /**
 * <div id="ds-priorityqueue.allocate" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\PriorityQueue::allocate</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\PriorityQueue::allocate</span> — <span class="dc-title">Allocates enough memory for a required capacity</span></p> </div> <div class="refsect1 description" id="refsect1-ds-priorityqueue.allocate-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\PriorityQueue::allocate</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$capacity</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">    Ensures that enough memory is allocated for a required capacity.    This removes the need to reallocate the internal buffer as values are added.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-priorityqueue.allocate-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">capacity</span></dt>    <dd>     <p class="para">        The number of values for which capacity should be allocated.     </p>     <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:         </p><p class="para">            Capacity will stay the same if this value is less than or equal to the            current capacity.        </p>    </blockquote>    <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:         </p><p class="para">            Capacity will always be rounded up to the nearest power of 2.        </p>     </blockquote>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-priorityqueue.allocate-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    没有返回值。  </p> </div> <div class="refsect1 examples" id="refsect1-ds-priorityqueue.allocate-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\PriorityQueue::allocate()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$queue </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\PriorityQueue</span><span style="color: #007700">();<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$queue</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">capacity</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">\$queue</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">allocate</span><span style="color: #007700">(</span><span style="color: #9876AA">100</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$queue</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">capacity</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(8)<br>int(128)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Allocates enough memory for a required capacity
         * @link https://www.php.net/manual/en/ds-priorityqueue.allocate.php
         *
         * @param int $capacity
         */
        public function allocate(int $capacity): void {}

        /**
 * <div id="ds-priorityqueue.capacity" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\PriorityQueue::capacity</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\PriorityQueue::capacity</span> — <span class="dc-title">Returns the current capacity</span></p> </div> <div class="refsect1 description" id="refsect1-ds-priorityqueue.capacity-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\PriorityQueue::capacity</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div>  <p class="para rdfs-comment">    Returns the current capacity.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-priorityqueue.capacity-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-priorityqueue.capacity-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    The current capacity.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-priorityqueue.capacity-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\PriorityQueue::capacity()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$queue </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\PriorityQueue</span><span style="color: #007700">();<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$queue</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">capacity</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(8)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Returns the current capacity
         * @link https://www.php.net/manual/en/ds-priorityqueue.capacity.php
         *
         * @return int
         */
        public function capacity(): int {}

        /**
 * <div id="ds-priorityqueue.clear" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\PriorityQueue::clear</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\PriorityQueue::clear</span> — <span class="dc-title">Removes all values</span></p> </div> <div class="refsect1 description" id="refsect1-ds-priorityqueue.clear-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\PriorityQueue::clear</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">    Removes all values from the queue.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-priorityqueue.clear-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-priorityqueue.clear-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   没有返回值。  </p> </div> <div class="refsect1 examples" id="refsect1-ds-priorityqueue.clear-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\PriorityQueue::clear()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$queue </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\PriorityQueue</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$queue</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">push</span><span style="color: #007700">(</span><span style="color: #DD0000">"a"</span><span style="color: #007700">,  </span><span style="color: #9876AA">5</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$queue</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">push</span><span style="color: #007700">(</span><span style="color: #DD0000">"b"</span><span style="color: #007700">, </span><span style="color: #9876AA">15</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$queue</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">push</span><span style="color: #007700">(</span><span style="color: #DD0000">"c"</span><span style="color: #007700">, </span><span style="color: #9876AA">10</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$queue</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">clear</span><span style="color: #007700">();<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$queue</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\PriorityQueue&nbsp;Object<br>(<br>)</blockquote></div>   </div>  </div> </div></div>
 * 
         * Removes all values from the collection.
         * @link https://www.php.net/manual/en/ds-collection.clear.php
         */
        public function clear(): void {}

        /**
 * <div id="ds-priorityqueue.copy" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\PriorityQueue::copy</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\PriorityQueue::copy</span> — <span class="dc-title">Returns a shallow copy of the queue</span></p> </div> <div class="refsect1 description" id="refsect1-ds-priorityqueue.copy-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\PriorityQueue::copy</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-priorityqueue.php" class="type Ds\PriorityQueue" style="color:#EAB766">Ds\PriorityQueue</a></span></div>  <p class="para rdfs-comment">    Returns a shallow copy of the queue.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-priorityqueue.copy-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-priorityqueue.copy-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   Returns a shallow copy of the queue.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-priorityqueue.copy-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\PriorityQueue::copy()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$queue </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\PriorityQueue</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$queue</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">push</span><span style="color: #007700">(</span><span style="color: #DD0000">"a"</span><span style="color: #007700">,  </span><span style="color: #9876AA">5</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$queue</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">push</span><span style="color: #007700">(</span><span style="color: #DD0000">"b"</span><span style="color: #007700">, </span><span style="color: #9876AA">15</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$queue</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">push</span><span style="color: #007700">(</span><span style="color: #DD0000">"c"</span><span style="color: #007700">, </span><span style="color: #9876AA">10</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$queue</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">copy</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\PriorityQueue&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;b<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;c<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;a<br>)</blockquote></div>   </div>  </div> </div></div>
