        /**
 * <div id="ds-priorityqueue.toarray" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\PriorityQueue::toArray</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\PriorityQueue::toArray</span> — <span class="dc-title">    Converts the queue to an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>  </span></p> </div> <div class="refsect1 description" id="refsect1-ds-priorityqueue.toarray-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\PriorityQueue::toArray</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>  <p class="para rdfs-comment">    Converts the queue to an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     </p><p class="para">        This method is not destructive.    </p>  </blockquote>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     </p><p class="para">        Casting to an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> is not supported yet.    </p>  </blockquote> </div> <div class="refsect1 parameters" id="refsect1-ds-priorityqueue.toarray-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-priorityqueue.toarray-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    An <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> containing all the values in the same order as the queue.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-priorityqueue.toarray-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\PriorityQueue::toArray()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$queue </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\PriorityQueue</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$queue</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">push</span><span style="color: #007700">(</span><span style="color: #DD0000">"a"</span><span style="color: #007700">,  </span><span style="color: #9876AA">5</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$queue</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">push</span><span style="color: #007700">(</span><span style="color: #DD0000">"b"</span><span style="color: #007700">, </span><span style="color: #9876AA">15</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$queue</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">push</span><span style="color: #007700">(</span><span style="color: #DD0000">"c"</span><span style="color: #007700">, </span><span style="color: #9876AA">10</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$queue</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">toArray</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">array(3)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"b"<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"c"<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"a"<br>}</blockquote></div>   </div>  </div> </div></div>
 * 
         * Converts the collection to an array.
         * <p><b>Note:</b> Casting to an array is not supported yet.</p>
         * @link https://www.php.net/manual/en/ds-collection.toarray.php
         * @return list<TValue> An array containing all the values in the same order as
         * the collection.
         */
        public function toArray(): array {}

        /**
